<?php $playlist = $playlist ?? []; $morceaux = $morceaux ?? []; $morceauxDisponibles = $morceauxDisponibles ?? []; ?>
<section class="detail-head"><a class="back-link" href="index.php?route=playlist/liste">← Mes playlists</a><div class="detail-layout"><div class="playlist-art art-<?= ((int) $playlist['id'] % 5) + 1 ?> large-art"><span>♫</span></div><div><p class="eyebrow">PLAYLIST</p><h1><?= htmlspecialchars($playlist['nom']) ?></h1><p class="detail-description">Une sélection pensée pour accompagner tes meilleurs moments.</p><p class="muted"><?= count($morceaux) ?> morceau(s) · créée par <?= htmlspecialchars($playlist['proprietaire']) ?></p><form method="post" action="index.php?route=playlist/supprimer" onsubmit="return confirm('Supprimer cette playlist ?')"><input type="hidden" name="id" value="<?= (int) $playlist['id'] ?>"><button class="button button-danger" type="submit">Supprimer</button></form></div></div></section>
<section class="detail-content"><div><div class="section-head compact"><div><p class="eyebrow">TRACKLIST</p><h2>Les morceaux</h2></div></div><div class="track-list"><?php if (empty($morceaux)): ?><div class="empty-state compact-empty"><h2>La playlist attend ses premiers morceaux.</h2></div><?php else: foreach ($morceaux as $index => $morceau): ?><article class="track-row"><div class="cover cover-<?= ($index % 6) + 1 ?> small-cover"><span><?= sprintf('%02d', $index + 1) ?></span></div><div class="track-row-info"><h3><?= htmlspecialchars($morceau['titre']) ?></h3><p><?= htmlspecialchars($morceau['artiste_nom']) ?></p></div><span class="track-row-duration"><?= sprintf('%02d:%02d', intdiv((int)($morceau['duree'] ?? 0), 60), (int)($morceau['duree'] ?? 0) % 60) ?></span><button class="play-button play-inline" type="button" data-audio="<?= htmlspecialchars($morceau['fichier_audio'] ?? '') ?>" data-title="<?= htmlspecialchars($morceau['titre']) ?>" data-artist="<?= htmlspecialchars($morceau['artiste_nom']) ?>">▶</button><form method="post" action="index.php?route=playlist/retirerMorceau"><input type="hidden" name="playlist_id" value="<?= (int) $playlist['id'] ?>"><input type="hidden" name="morceau_id" value="<?= (int) $morceau['id'] ?>"><button class="icon-button" title="Retirer" type="submit">×</button></form></article><?php endforeach; endif; ?></div></div><aside class="add-track-panel"><p class="eyebrow">ADD TRACK</p><h2>Enrichir la vibe</h2><form class="vibely-form" method="post" action="index.php?route=playlist/ajouterMorceau"><input type="hidden" name="playlist_id" value="<?= (int) $playlist['id'] ?>"><select name="morceau_id" required><option value="">Choisir un morceau</option><?php foreach ($morceauxDisponibles as $disponible): ?><option value="<?= (int) $disponible['id'] ?>"><?= htmlspecialchars($disponible['titre']) ?> · <?= htmlspecialchars($disponible['artiste_nom']) ?></option><?php endforeach; ?></select><button class="button button-primary" type="submit">Ajouter le morceau</button></form></aside></section>
